atlas_ui <- function(d) {
  library(shiny)
  fluidPage(
    tags$head(tags$title('Conservation priorities | Victoria'),
      tags$meta(name='viewport',content='width=device-width, initial-scale=1'),
      tags$link(rel='stylesheet',href='atlas.css'),tags$script(src='atlas.js')),
    tags$a(href='#main',class='skip-link','Skip to content'),
    tags$header(class='masthead',
      div(class='heading',h1('Conservation priorities'),p('Mapping Conservation Priorities and Tracking Biodiversity Management in Victoria')),
      tags$nav(`aria-label`='Main navigation',
        tags$button(type='button',class='nav-link active',`data-page`='explore','Explore priorities'),
        tags$button(type='button',class='nav-link',`data-page`='progress','Review progress'),
        tags$button(type='button',class='nav-link',`data-page`='sources','Sources & methods'))),
    tags$main(id='main',
      div(id='page-explore',class='atlas-page',
        div(class='context-line','Victoria',span('SMP version 4'),span('Modelled opportunities')),
        div(class='workspace',
          tags$aside(class='control-rail',`aria-label`='Map controls',
            selectInput('action','Management action',choices=setNames(names(action_labels),action_labels),selected='Control Foxes'),
            selectizeInput('area','Summary area',choices=setNames(d$areas$microID,d$areas$Name),selected='unit668',options=list(placeholder='Search a unit number',maxOptions=100)),
            actionButton('pin','Pin this area',class='button-primary'),
            div(class='pin-section',h3('Pinned areas'),uiOutput('pinned'),textOutput('pin_message')),
            actionButton('clear','Clear comparison',class='button-outline'),
            downloadButton('download_compare','Download comparison',class='button-dark'),
            actionButton('reset','Reset view',class='text-button'),
            div(class='rail-note','Select a place on the map. Pin up to three areas to compare their actions.')),
          div(class='map-region',leaflet::leafletOutput('priority_map',height='520px'),
            div(class='map-caption',span('Higher rank = greater relative cost-effectiveness'),span('Select a polygon to inspect'))),
          tags$aside(class='detail-rail',`aria-label`='Selected area',uiOutput('area_detail'))),
        tags$section(class='heatmap-section',
          div(class='section-heading',h2('Compare actions across areas'),p('Each cell shows a relative rank from 0 to 100. Select a cell to explore its area and action.')),
          uiOutput('heatmap')),
        tags$section(class='comparison-section',
          div(class='section-heading',h2('Compare opportunity extent'),radioButtons('extent_unit',NULL,choices=c('Share of relevant area'='pct','Hectares'='ha'),inline=TRUE)),
          uiOutput('comparison'),
          p(class='caption','Top 5% is included within top 15%. Bars share a scale within this comparison. Areas for different actions may overlap.'))),
      div(id='page-progress',class='atlas-page',hidden=NA,
        div(class='context-line','Victoria',span('2018-19 to 2021-22'),span('Reported management activity')),
        div(class='progress-intro',h2('How much work has been reported?'),
          p('Compare reported activity with policy targets. These figures include work by government, community and other organisations across Victoria.'),
          p(class='caption','Statewide totals remain independent of your map selection. Figures describe management activity, not measured biodiversity recovery.')),
        div(class='progress-controls',selectInput('year','Financial year',choices=unique(d$activity$financial_year),selected='2021-22'),
          selectInput('trend_action','Highlight action',choices=c('All actions',unique(annual_progress(d)$action))),downloadButton('download_activity','Download activity data')),
        div(class='progress-grid',
          tags$section(h3('Distance from the annual target'),p(class='caption','Dots show target attainment. The line at 100% marks the annual target.'),plotOutput('target_gap',height='280px'),uiOutput('target_table')),
          tags$section(h3('Annual control in priority locations'),p(class='caption','Reported hectares. Dashed lines show each action\'s annual target.'),plotOutput('annual_trends',height='430px')),
          tags$section(h3('Where reported control took place'),p(class='caption','Share of statewide activity occurring in priority locations.'),plotOutput('priority_share',height='320px')),
          tags$section(h3('Restoration and permanent protection'),p(class='caption','Cumulative hectares since 2017. Each measure has a 200,000 ha target by 2037.'),plotOutput('cumulative',height='320px'),
            p(class='method-note','Revegetation: the increase around 2020-21 partly reflects a change in reporting method. Revegetation uses priority locations; protection uses statewide private-land totals.'))),
        tags$section(class='tableau-section',h3('Tableau view'),uiOutput('tableau'))),
      div(id='page-sources',class='atlas-page reading-page',hidden=NA,
        h2('Read the evidence behind the map'),
        div(class='source-grid',
          tags$section(h3('Modelled priorities'),p('Strategic Management Prospects version 4 compares conservation opportunities across Victoria. The app uses median cost-effectiveness ranks and hectares from DEECA\'s public summary-area service.'),
            tags$dl(tags$dt('Coverage'),tags$dd(paste(number(nrow(d$areas)),'summary areas;',number(nrow(d$actions)),'action records; 16 actions.')),
              tags$dt('Model release'),tags$dd('July 2023'),tags$dt('Data retrieved'),tags$dd(d$retrieved),tags$dt('Spatial preparation'),tags$dd('Geometry repaired and simplified to 100 metres for display. Hectares are taken from the source attributes.')),
            tags$a(href='https://www.environment.vic.gov.au/biodiversity/naturekit/nk-datalists',target='_blank',rel='noopener','NatureKit dataset guide')),
          tags$section(h3('Reported management'),p('The Biodiversity 2037 progress report supplies four financial years of activity. Values were transcribed from printed pages 5, 7, 11, 15 and 19.'),
            p('Herbivore, predator and weed control are annual measures. Revegetation and permanent protection are cumulative since 2017. Statewide totals already include priority and other locations.'),
            tags$a(href=d$activity$source_url[1],target='_blank',rel='noopener','Read the original progress report')),
          tags$section(h3('How to interpret a rank'),p('A rank of 88 is a relative model ranking. It is not an 88% improvement, a probability or a dollar return. Do not add ranks together.'),
            p('The top-15% field is named AREA_20 in the service. The interface follows NatureKit\'s display label. Benefit-rank fields are omitted because available sources disagree about their aggregation.')),
          tags$section(h3('What is missing'),p('An absent action record is shown as missing, rather than zero. Unit 925 has no action records. Site access, actual project costs, local delivery and current ecological condition are outside this dataset.'),
            p('Downloaded area reports can differ from the live service. The app consistently uses one service snapshot. An official report link is provided for further reading, with that difference made explicit.'))),
        div(class='method-note','Student coursework prototype for DEECA public servants. Source attribution: State of Victoria, Department of Energy, Environment and Climate Action. This application does not represent departmental advice.'))),
    tags$footer(span('State of Victoria / DEECA'),span('Conservation priorities & management progress'),span('Student project  /  R Shiny'))
  )
}
